mapper.update:
UPDATE contract
SET status = 'completed', update_by = #{updateBy}
WHERE id = #{id} AND buyer_tenant_id = #{tenantId}
  AND (status = 'signed' OR status = 'completed') AND is_deleted = 0

mapper.select:
SELECT COUNT(*) FROM contract
WHERE inquiry_id = #{inquiryId} AND winning_quote_id = #{winningQuoteId}
AND status != 'terminated' AND is_deleted = 0

mapper.update:
UPDATE contract
SET status = 'pending_supplier', withdrawn_at = NULL, update_by = #{updateBy}
WHERE id = #{id} AND buyer_tenant_id = #{tenantId}
  AND status = 'draft' AND is_deleted = 0

UPDATE contract
SET supplier_confirmed = 1, supplier_confirmed_at = NOW(), update_by = #{updateBy}
WHERE id = #{id} AND supplier_tenant_id = #{tenantId}
  AND status = 'pending_supplier' AND is_deleted = 0

UPDATE contract
SET status = 'draft', supplier_confirmed = 0, supplier_confirmed_at = NULL,
    decline_reason = #{reason}, update_by = #{updateBy}
WHERE id = #{id} AND supplier_tenant_id = #{tenantId}
  AND status = 'pending_supplier' AND is_deleted = 0

